CREATE TABLE IF NOT EXISTS gis_phase353_feature_lineage (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version TEXT NOT NULL, candidate_id UUID NOT NULL, source_feature_id UUID NOT NULL, target_feature_id UUID NOT NULL, source_dataset_id TEXT, target_dataset_id TEXT, source_feature_key TEXT, target_feature_key TEXT, source_parent_id TEXT, target_parent_id TEXT, source_provider TEXT, target_provider TEXT, source_state_code TEXT, target_state_code TEXT, source_srid INTEGER, target_srid INTEGER, source_normalized_srid INTEGER, target_normalized_srid INTEGER, lineage_status TEXT NOT NULL, lineage_score DOUBLE PRECISION NOT NULL DEFAULT 0, issues JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,candidate_id));